<section class="builder-block" id="seats-<?= e($program['id']) ?>"><div class="builder-block-heading"><div><span class="step-chip">B</span><div><h3>Seat matrix</h3><p>Category rows must add up to programme capacity. Allocated rows cannot be reduced below filled seats.</p></div></div><span class="count-badge"><?= number_format((int)$program['matrix_total']) ?>/<?= number_format((int)$program['seat_capacity']) ?></span></div><?php if($manageSeats):?><form method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/programs/'.$program['id'].'/seats') ?>"><?= csrf_field() ?><div class="seat-editor"><label class="capacity-field"><span>Programme capacity</span><input type="number" min="1" name="seat_capacity" value="<?= e($program['seat_capacity']) ?>" required></label><?php foreach($program['seats'] as $seat):?><label><span><?= e($seat['category'].' · '.$seat['quota']) ?><small><?= e($seat['filled_seats']) ?> currently allocated</small></span><input type="number" min="<?= e($seat['filled_seats']) ?>" name="seats[<?= e($seat['id']) ?>]" value="<?= e($seat['seats']) ?>" required></label><?php endforeach?></div><details class="inline-builder"><summary>+ Add another category/quota row</summary><div class="form-grid three"><label><span>Category</span><select name="new_category"><option value="">Choose category</option><?php foreach($categories as $category):?><option value="<?= e($category['code']) ?>"><?= e($category['name']) ?></option><?php endforeach?></select></label><label><span>Quota key</span><input name="new_quota" value="state"></label><label><span>Seats</span><input type="number" min="0" name="new_seats" value="0"></label></div></details><button class="button button-outline">Save capacity and seats</button></form><?php foreach($program['seats'] as $seat): if((int)$seat['filled_seats']===0&&count($program['seats'])>1):?><form class="compact-danger-row" method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/programs/'.$program['id'].'/seats/'.$seat['id