ired></label><label><span>Late fee</span><input type="number" min="0" step=".01" name="late_fee_amount" value="<?= e($fee['late_fee_amount']) ?>"></label><label><span>Due date</span><input type="datetime-local" name="due_at" value="<?= $fee['due_at']?e(date('Y-m-d\TH:i',strtotime($fee['due_at']))):'' ?>"></label><label class="span-2"><span>Refund policy</span><textarea name="refund_policy"><?= e($fee['refund_policy']) ?></textarea></label></div><button class="button button-outline">Update fee rule</button></form><form method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/programs/'.$program['id'].'/fees/'.$fee['id'].'/delete') ?>"><?= csrf_field() ?><button class="text-button danger" data-confirm="Delete this unused fee rule?">Delete rule</button></form><?php endif?></details><?php endforeach?></div><?php if($manageFees):?><details class="inline-builder"><summary>+ Add fee rule</summary><form method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/programs/'.$program['id'].'/fees') ?>"><?= csrf_field() ?><div class="form-grid three"><label><span>Fee type</span><select name="fee_type"><option value="application_fee">Application fee</option><option value="admission_fee">Admission fee</option></select></label><label><span>Category override</span><select name="category_code"><option value="">All categories</option><?php foreach($categories as $category):?><option value="<?= e($category['code']) ?>"><?= e($category['name']) ?></option><?php endforeach?></select></label><label><span>Label</span><input name="label" required></label><label><span>Amount</span><input type="number" min="0" step=".01" name="amount" required></label><label><span>Due date</span><input type="datetime-local" name="due_at"></label><label><span>Late fee</span><input type="number" min="0" step=".01" name="late_fee_amount" value="0"></label><label class="full"><span>Refund policy</span><textarea name="refund_policy"></textarea></label></div><button class="button button-primary">Add 