<section class="card" id="form-builder"><div class="workspace-section-heading"><div><span class="eyebrow">Step 3</span><h2>Application form builder</h2><p>Sections and fields are ordered numerically. Open any record to change its label, type, options, binding, condition or state.</p></div><span class="count-badge"><?= count($sections) ?> sections · <?= count($fields) ?> fields</span></div><div class="builder-columns"><div><h3>Form sections</h3><div class="editable-record-list"><?php foreach($sections as $section): $sectionFieldCount=count(array_filter($fields,fn($field)=>(int)$field['section_id']===(int)$section['id']));?><details class="editable-record"><summary><div><b><?= e($section['title']) ?></b><small><code><?= e($section['section_key']) ?></code> · <?= $sectionFieldCount ?> fields · order <?= e($section['sort_order']) ?> · <?= e($section['status']) ?></small></div><span>Edit</span></summary><?php if($manageForms):?><form method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/form-sections') ?>"><?= csrf_field() ?><input type="hidden" name="section_id" value="<?= e($section['id']) ?>"><label><span>Section key</span><input name="section_key" value="<?= e($section['section_key']) ?>" required></label><label><span>Title</span><input name="title" value="<?= e($section['title']) ?>" required></label><label><span>Description</span><textarea name="description"><?= e($section['description']) ?></textarea></label><div class="form-grid"><label><span>Sort order</span><input type="number" name="sort_order" value="<?= e($section['sort_order']) ?>"></label><label><span>State</span><select name="status"><option value="active"<?= selected($section['status'],'active') ?>>Active</option><option value="inactive"<?= selected($section['status'],'inactive') ?>>Inactive</option></select></label></div><button class="button button-outline">Update section</button></form><?php if($sectionFieldCount===0):?><form method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/form-sections/'.$section['id'].'/delete') ?>"><?= csrf_field() ?><button class="text-button danger" data-confirm="Delete this empty section?">Delete section</button></form><?php endif?><?php endif?></details><?php endforeach?></div><?php if($manageForms):?><details class="inline-builder"><summary>+ Add section</summary><form method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/form-sections') ?>"><?= csrf_field() ?><label><span>Section key</span><input name="section_key" required></label><label><span>Title</span><input name="title" required></label><label><span>Description</span><input name="description"></label><label><span>Sort order</span><input type="number" name="sort_order" value="100"></label><button class="button button-primary">Add section</button></form></details><?php endif?></div>
<div><h3>Configured fields</h3><div class="editable-record-list field-records"><?php foreach($fields as $field):?><details class="editable-record"><summary><div><b><?= e($field['label']) ?></b><small><?= e($sectionNames[(int)$field['section_id']]??'Unknown section') ?> · <code><?= e($field['field_key']) ?></code> · <?= e($field['field_type']) ?> · <?= $field['is_required']?'required':'optional' ?> · <?= e($field['status']) ?></small></div><span>Edit</span></summary><?php if($manageForms):?><form method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/form-fields') ?>"><?= csrf_field() ?><input type="hidden" name="field_id" value="<?= e($field['id']) ?>"><div class="form-grid"><label><span>Section</span><select name="section_id" required><?php foreach($sections as $section):?><option value="<?= e($section['id']) ?>"<?= selected($field['section_id'],$section['id']) ?>><?= e($section['title']) ?></option><?php endforeach?></select></label><label><span>Field key</span><input name="field_key" value="<?= e($field['field_key']) ?>" required></label><label><span>Label</span><input name="label" value="<?= e($field['label']) ?>" required></label><label><span>Field type</span><select name="field_type"><?php foreach(['text','textarea','email','tel','number','date','select','radio','checkbox','multiselect','file'] as $type):?><option value="<?= e($type) ?>"<?= selected($field['field_type'],$type) ?>><?= e($type) ?></option><?php endforeach?></select></label><label><span>Canonical binding</span><input name="canonical_binding" value="<?= e($field['canonical_binding']) ?>" placeholder="Leave blank for custom response"></label><label><span>Placeholder</span><input name="placeholder" value="<?= e($field['placeholder']) ?>"></label><label><span>Sort order</span><input type="number" name="sort_order" value="<?= e($field['sort_order']) ?>"></label><label><span>State</span><select name="status"><option value="active"<?= selected($field['status'],'active') ?>>Active</option><option value="inactive"<?= selected($field['status'],'inactive') ?>>Inactive</option></select></label><label class="full"><span>Help text</span><input name="help_text" value="<?= e($field['help_text']) ?>"></label><label class="full"><span>Options — one per line as value|Label</span><textarea name="options" rows="5"><?= e($optionsText($field['options_json'])) ?></textarea></label><label class="full"><span>Conditional rule JSON</span><textarea name="conditional_rules" rows="3" placeholder='{"field":"category","operator":"eq","value":"SC"}'><?= e($field['conditional_rules']) ?></textarea></label><label class="check-control"><input type="checkbox" name="is_required" value="1" <?= checked($field['is_required']) ?>><span>Required</span></label><label class="check-control"><input type="checkbox" name="is_searchable" value="1" <?= checked($field['is_searchable']) ?>><span>Searchable</span></label></div><button class="button button-outline">Update field</button></form><form method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/form-fields/'.$field['id'].'/delete') ?>"><?= csrf_field() ?><button class="text-button danger" data-confirm="Delete this unused field? Use Inactive if applications may depend on it.">Delete field</button></form><?php endif?></details><?php endforeach?></div><?php if($manageForms&&$sections):?><details class="inline-builder"><summary>+ Add field</summary><form method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/form-fields') ?>"><?= csrf_field() ?><div class="form-grid"><label><span>Section</span><select name="section_id" required><?php foreach($sections as $section):?><option value="<?= e($section['id']) ?>"><?= e($section['title']) ?></option><?php endforeach?></select></label><label><span>Field key</span><input name="field_key" required></label><label><span>Label</span><input name="label" required></label><label><span>Field type</span><select name="field_type"><?php foreach(['text','textarea','email','tel','number','date','select','radio','checkbox','multiselect','file'] as $type):?><option value="<?= e($type) ?>"><?= e($type) ?></option><?php endforeach?></select></label><label><span>Canonical binding</span><input name="canonical_binding" placeholder="document:code for file fields"></label><label><span>Placeholder</span><input name="placeholder"></label><label><span>Sort order</span><input type="number" name="sort_order" value="100"></label><label class="full"><span>Help text</span><input name="help_text"></label><label class="full"><span>Options — value|Label, one per line</span><textarea name="options"></textarea></label><label class="full"><span>Conditional rule JSON</span><textarea name="conditional_rules" placeholder='{"field":"category","operator":"eq","value":"SC"}'></textarea></label><label class="check-control"><input type="checkbox" name="is_required" value="1"><span>Required</span></label><label class="check-control"><input type="checkbox" name="is_searchable" value="1"><span>Searchable</span></label></div><button class="button button-primary">Add field</button></form></details><?php endif?></div></div></section>

<section class="card" id="documents"><div class="workspace-section-heading"><div><span class="eyebrow">Step 4</span><h2>Document requirements</h2><p>Open a requirement to change document type, programme/category scope, stage, required state or order.</p></div><span class="count-badge"><?= count($requirements) ?> requirements</span></div><div class="editable-record-list document-records"><?php foreach($requirements as $requirement):?><details class="editable-record"><summary><div><b><?= e($requirement['name']) ?></b><small><?= e($requirement['program_name']?:'All programmes') ?> · <?= e($requirement['category']?:'All categories') ?> · <?= e($requirement['stage']) ?> · <?= $requirement['is_required']?'required':'optional' ?></small></div><span>Edit</span></summary><?php if($manageDocuments):?><form method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/documents') ?>"><?= csrf_field() ?><input type="hidden" name="requirement_id" value="<?= e($requirement['id']) ?>"><div class="form-grid three"><label><span>Document type</span><select name="document_type_id" required><?php foreach($documentTypes as $type):?><option value="<?= e($type['id']) ?>"<?= selected($requirement['document_type_id'],$type['id']) ?>><?= e($type['name']) ?></option><?php endforeach?></select></label><label><span>Programme scope</span><select name="program_id"><option value="">All programmes</option><?php foreach($programs as $program):?><option value="<?= e($program['program_id']) ?>"<?= selected($requirement['program_id'],$program['program_id']) ?>><?= e($program['name']) ?></option><?php endforeach?></select></label><label><span>Category scope</span><select name="category"><option value="">All categories</option><?php foreach($categories as $category):?><option value="<?= e($category['code']) ?>"<?= selected($requirement['category'],$category['code']) ?>><?= e($category['name']) ?></option><?php endforeach?></select></label><label><span>Stage</span><select name="stage"><option value="application"<?= selected($requirement['stage'],'application') ?>>Application</option><option value="admission"<?= selected($requirement['stage'],'admission') ?>>Admission</option></select></label><label><span>Sort order</span><input type="number" name="sort_order" value="<?= e($requirement['sort_order']) ?>"></label><label class="check-control"><input type="checkbox" name="is_required" value="1" <?= checked($requirement['is_required']) ?>><span>Required</span></label></div><button class="button button-outline">Update requirement</button></form><form method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/documents/'.$requirement['id'].'/delete') ?>"><?= csrf_field() ?><button class="text-button danger" data-confirm="Delete this unused document requirement?">Delete requirement</button></form><?php endif?></details><?php endforeach?></div><?php if($manageDocuments):?><details class="inline-builder"><summary>+ Add document requirement</summary><form method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/documents') ?>"><?= csrf_field() ?><div class="form-grid three"><label><span>Document type</span><select name="document_type_id" required><?php foreach($documentTypes as $type):?><option value="<?= e($type['id']) ?>"><?= e($type['name']) ?></option><?php endforeach?></select></label><label><span>Programme scope</span><select name="program_id"><option value="">All programmes</option><?php foreach($programs as $program):?><option value="<?= e($program['program_id']) ?>"><?= e($program['name']) ?></option><?php endforeach?></select></label><label><span>Category scope</span><select name="category"><option value="">All categories</option><?php foreach($categories as $category):?><option value="<?= e($category['code']) ?>"><?= e($category['name']) ?></option><?php endforeach?></select></label><label><span>Stage</span><select name="stage"><option value="application">Application</option><option value="admission">Admission</option></select></label><label><span>Sort order</span><input type="number" name="sort_order" value="100"></label><label class="check-control"><input type="checkbox" name="is_required" value="1"><span>Required</span></label></div><button class="button button-primary">Add requirement</button></form></details><?php endif?></section>

<section class="card" id="versions"><div class="workspace-section-heading"><div><span class="eyebrow">Step 5</span><h2>Configuration versions</h2><p>Published snapshots are immutable and identified by SHA-256 hashes.</p></div></div><?php if(!$versions):?><p>No published version yet.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>Version</th><th>Status</th><th>Hash</th><th>Published by</th><th>Time</th></tr></thead><tbody><?php foreach($versions as $version):?><tr><td><b>v<?= e($version['version_no']) ?></b></td><td><?= e($version['status']) ?></td><td><code><?= e(substr($version['snapshot_hash'],0,18)) ?>…</code></td><td><?= e($version['creator_name']?:'System migration') ?></td><td><?= format_date($version['created_at'],true) ?></td></tr><?php endforeach?></tbody></table></div><?php endif?></section>

<?php if(can('admissions.duplicate')):?><section class="card" id="duplicate"><div class="workspace-section-heading"><div><span class="eyebrow">Safe reuse</span><h2>Duplicate as an editable draft</h2><p>Configuration is copied; applications, payments, allocations and filled-seat counts are never copied.</p></div></div><form method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/duplicate') ?>"><?= csrf_field() ?><input type="hidden" name="academic_session_id" value="<?= e($cycle['academic_session_id']) ?>"><div class="form-grid three"><label><span>New name</span><input name="name" required></label><label><span>New code</span><input name="code" required></label><label><span>New slug</span><input name="slug" required></label><label><span>Opening</span><input type="datetime-local" name="starts_at" required></label><label><span>Closing</span><input type="datetime-local" name="ends_at" required></label><label><span>Correction deadline</span><input type="datetime-local" name="correction_deadline"></label></div><button class="button button-outline" data-confirm="Create a separate draft copy?">Duplicate cycle</button></form></section><?php endif?>
</div>
